contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: from initial holder will be address(this) because constructor of C set owner to deployer (which is this test deploying c in checker),
    // but checker deploys a fresh C and then passes it into this test constructor. The test will try transfers from this contract (which initially holds all tokens).
    // We accept arbitrary to and value. We need to ensure we don't overflow when summing, so we read balances first and use uint256 local sums.
    function run(address to, uint256 value) public payable {
        require(true);

        // Observe pre-state
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balFromBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balToBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // Attempt transfer and capture whether it reverted
        bool reverted;
        bool ok = c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe post-state
        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balFromAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balToAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // General rule (single assert):
        // - totalSupply must never change due to transfer (whether it reverted or succeeded)
        // - if transfer succeeded, sender balance decreased by value and recipient increased by value
        // - if transfer reverted, both balances unchanged
        assert(
            totalAfter == totalBefore
            && (
                reverted
                ? (balFromAfter == balFromBefore && balToAfter == balToBefore)
                : (balFromBefore >= value && balFromAfter + value == balFromBefore && balToAfter == balToBefore + value)
            )
        );
    }

    receive() external payable { }
}

